1	package loganalyzer
2	
3	import (
4		"fmt"
5		"os"
6		"time"
7	)
8	
9	// Logger provides simple structured logging
10	type Logger struct {
11		component string
12		output    *os.File
13	}
14	
15	// NewLogger creates a logger for a component
16	func NewLogger(component string) *Logger {
17		return &Logger{
18			component: component,
19			output:    os.Stderr,
20		}
21	}
22	
23	func (l *Logger) log(level, format string, args ...interface{}) {
24		msg := fmt.Sprintf(format, args...)
25		ts := time.Now().Format("2006-01-02 15:04:05")
26		fmt.Fprintf(l.output, "[%s] %s %s: %s\n", ts, level, l.component, msg)
27	}
28	
29	// Debug logs a debug message
30	func (l *Logger) Debug(format string, args ...interface{}) {
31		l.log("DEBUG", format, args...)
32	}
33	
34	// Info logs an info message
35	func (l *Logger) Info(format string, args ...interface{}) {
36		l.log("INFO", format, args...)
37	}
38	
39	// Error logs an error message
40	func (l *Logger) Error(format string, args ...interface{}) {
41		l.log("ERROR", format, args...)
42	}
43

