1	package loganalyzer
2	
3	import (
4		"bufio"
5		"fmt"
6		"io"
7		"regexp"
8		"strings"
9		"time"
10	)
11	
12	// ParserConfig holds parser configuration
13	type ParserConfig struct {
14		// TimestampFormat is the Go time format string
15		TimestampFormat string
16		// CustomPattern allows custom regex with named groups
17		CustomPattern string
18	}
19	
20	// DefaultConfig returns a standard parser config
21	func DefaultConfig() ParserConfig {
22		return ParserConfig{
23			TimestampFormat: "2006-01-02 15:04:05",
24		}
25	}
26	
27	// Standard log pattern: 2024-01-15 10:30:45 ERROR Something failed
28	var standardPattern = regexp.MustCompile(
29		`^(\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2})\s+(DEBUG|INFO|WARN|WARNING|ERROR|FATAL)\s+(.+)$`,
30	)
31	
32	// Parser handles log file parsing
33	type Parser struct {
34		config  ParserConfig
35		pattern *regexp.Regexp
36		logger  *Logger
37	}
38	
39	// NewParser creates a new log parser
40	func NewParser(config ParserConfig) *Parser {
41		p := &Parser{
42			config: config,
43			logger: NewLogger("parser"),
44		}
45	
46		if config.CustomPattern != "" {
47			p.pattern = regexp.MustCompile(config.CustomPattern)
48		} else {
49			p.pattern = standardPattern
50		}
51	
52		return p
53	}
54	
55	// ParseReader parses logs from an io.Reader
56	func (p *Parser) ParseReader(r io.Reader) ([]LogEntry, error) {
57		var entries []LogEntry
58		scanner := bufio.NewScanner(r)
59		lineNum := 0
60	
61		for scanner.Scan() {
62			lineNum++
63			line := scanner.Text()
64	
65			if strings.TrimSpace(line) == "" {
66				continue
67			}
68	
69			entry, err := p.parseLine(line)
70			if err != nil {
71				p.logger.Debug("skipping line %d: %v", lineNum, err)
72				continue
73			}
74	
75			entries = append(entries, entry)
76		}
77	
78		if err := scanner.Err(); err != nil {
79			return entries, fmt.Errorf("reading input: %w", err)
80		}
81	
82		p.logger.Info("parsed %d log entries", len(entries))
83		return entries, nil
84	}
85	
86	// parseLine parses a single log line
87	func (p *Parser) parseLine(line string) (LogEntry, error) {
88		matches := p.pattern.FindStringSubmatch(line)
89		if matches == nil {
90			return LogEntry{}, fmt.Errorf("line does not match pattern: %s", line)
91		}
92	
93		// Extract named groups
94		names := p.pattern.SubexpNames()
95		groups := make(map[string]string)
96		for i, name := range names {
97			if i > 0 && name != "" {
98				groups[name] = matches[i]
99			}
100		}
101	
102		// Standard format parsing
103		if len(matches) >= 4 {
104			ts, err := time.Parse(p.config.TimestampFormat, matches[1])
105			if err != nil {
106				return LogEntry{}, fmt.Errorf("parsing timestamp: %w", err)
107			}
108	
109			return LogEntry{
110				Timestamp: ts,
111				Level:     ParseLevel(matches[2]),
112				Message:   matches[3],
113				Fields:    groups,
114				Raw:       line,
115			}, nil
116		}
117	
118		// Custom pattern with named groups
119		return LogEntry{
120			Fields: groups,
121			Raw:    line,
122		}, nil
123	}
124	
125	// ParseLines parses multiple log lines from a string
126	func (p *Parser) ParseLines(text string) ([]LogEntry, error) {
127		return p.ParseReader(strings.NewReader(text))
128	}
129

