1	package loganalyzer
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// Analyzer processes log entries and generates statistics
11	type Analyzer struct {
12		entries []LogEntry
13		logger  *Logger
14	}
15	
16	// NewAnalyzer creates a new analyzer
17	func NewAnalyzer() *Analyzer {
18		return &Analyzer{
19			logger: NewLogger("analyzer"),
20		}
21	}
22	
23	// SetEntries loads entries for analysis
24	func (a *Analyzer) SetEntries(entries []LogEntry) {
25		a.entries = entries
26	}
27	
28	// Stats computes overall statistics
29	func (a *Analyzer) Stats() LogStats {
30		stats := LogStats{
31			LevelCounts: make(map[LogLevel]int),
32		}
33	
34		if len(a.entries) == 0 {
35			return stats
36		}
37	
38		stats.TotalEntries = len(a.entries)
39		stats.FirstTimestamp = a.entries[0].Timestamp
40		stats.LastTimestamp = a.entries[0].Timestamp
41	
42		// Count messages for top messages
43		msgCounts := make(map[string]int)
44	
45		for _, e := range a.entries {
46			stats.LevelCounts[e.Level]++
47	
48			if e.Timestamp.Before(stats.FirstTimestamp) {
49				stats.FirstTimestamp = e.Timestamp
50			}
51			if e.Timestamp.After(stats.LastTimestamp) {
52				stats.LastTimestamp = e.Timestamp
53			}
54	
55			msgCounts[e.Message]++
56		}
57	
58		// Calculate error rate
59		errorCount := stats.LevelCounts[ERROR] + stats.LevelCounts[FATAL]
60		if stats.TotalEntries > 0 {
61			stats.ErrorRate = float64(errorCount) / float64(stats.TotalEntries) * 100
62		}
63	
64		// Get top messages
65		stats.TopMessages = topMessages(msgCounts, 10)
66	
67		a.logger.Info("analyzed %d entries, error rate: %.2f%%", stats.TotalEntries, stats.ErrorRate)
68		return stats
69	}
70	
71	// FilterByLevel returns entries matching the given level
72	func (a *Analyzer) FilterByLevel(level LogLevel) []LogEntry {
73		var filtered []LogEntry
74		for _, e := range a.entries {
75			if e.Level == level {
76				filtered = append(filtered, e)
77			}
78		}
79		return filtered
80	}
81	
82	// FilterByTimeRange returns entries within the time range
83	func (a *Analyzer) FilterByTimeRange(tr TimeRange) []LogEntry {
84		var filtered []LogEntry
85		for _, e := range a.entries {
86			if !e.Timestamp.Before(tr.Start) && !e.Timestamp.After(tr.End) {
87				filtered = append(filtered, e)
88			}
89		}
90		return filtered
91	}
92	
93	// FilterByMessage returns entries containing the substring
94	func (a *Analyzer) FilterByMessage(substr string) []LogEntry {
95		var filtered []LogEntry
96		for _, e := range a.entries {
97			if strings.Contains(strings.ToLower(e.Message), strings.ToLower(substr)) {
98				filtered = append(filtered, e)
99			}
100		}
101		return filtered
102	}
103	
104	// ErrorsByHour groups errors by hour for trend analysis
105	func (a *Analyzer) ErrorsByHour() map[time.Time]int {
106		hourly := make(map[time.Time]int)
107		for _, e := range a.entries {
108			if e.Level == ERROR || e.Level == FATAL {
109				hour := e.Timestamp.Truncate(time.Hour)
110				hourly[hour]++
111			}
112		}
113		return hourly
114	}
115	
116	// Summary returns a human-readable summary
117	func (a *Analyzer) Summary() string {
118		stats := a.Stats()
119	
120		var sb strings.Builder
121		sb.WriteString(fmt.Sprintf("Total entries: %d\n", stats.TotalEntries))
122		sb.WriteString(fmt.Sprintf("Time range: %s to %s\n",
123			stats.FirstTimestamp.Format(time.RFC3339),
124			stats.LastTimestamp.Format(time.RFC3339)))
125		sb.WriteString(fmt.Sprintf("Error rate: %.2f%%\n\n", stats.ErrorRate))
126	
127		sb.WriteString("Level breakdown:\n")
128		for _, level := range []LogLevel{DEBUG, INFO, WARN, ERROR, FATAL} {
129			count := stats.LevelCounts[level]
130			if count > 0 {
131				sb.WriteString(fmt.Sprintf("  %s: %d\n", level, count))
132			}
133		}
134	
135		if len(stats.TopMessages) > 0 {
136			sb.WriteString("\nTop messages:\n")
137			for _, mc := range stats.TopMessages {
138				sb.WriteString(fmt.Sprintf("  [%d] %s\n", mc.Count, mc.Message))
139			}
140		}
141	
142		return sb.String()
143	}
144	
145	func topMessages(counts map[string]int, limit int) []MessageCount {
146		msgs := make([]MessageCount, 0, len(counts))
147		for msg, count := range counts {
148			msgs = append(msgs, MessageCount{Message: msg, Count: count})
149		}
150	
151		sort.Slice(msgs, func(i, j int) bool {
152			return msgs[i].Count > msgs[j].Count
153		})
154	
155		if len(msgs) > limit {
156			msgs = msgs[:limit]
157		}
158	
159		return msgs
160	}
161

